// SCMaker: bass. Velocity controls amplitude; gate controls note length.
SynthDef(\t_bass, { |out = 0, freq = 110, amp = 0.16, gate = 1, brightness = 1800, drive = 0.15, attack = 0.008, decay = 0.2, sustain = 0.65, release = 0.24, detune = 0.002|
    var signal, envelope;
    signal = Saw.ar(freq * [1 - detune, 1 + detune]);
    signal = LPF.ar(signal, brightness.clip(120, 18000));
    signal = (signal * (1 + (drive * 8))).tanh / (1 + (drive * 2));
    envelope = EnvGen.kr(Env.adsr(attack, decay, sustain, release), gate, doneAction: 2);
    Out.ar(out, signal * envelope * amp);
}).add;

